import { filterBySpecialty } from '../src/api/api';

describe('filterBySpecialty', () => {
  beforeEach(() => {
    mockGetRequest.mockReset();
    mockGetRequest.mockResolvedValue({
      data: {
        success: true,
        data: [],
      },
    });
  });

  test('requests the next GP queue when joining the consult room', async () => {
    await filterBySpecialty({
      planId: 'plan-1',
      serviceType: 'eQueuingTele',
      orderBy: 'queue',
      showOffline: false,
      doctorType: 'GP',
    });

    const requestUrl = String(mockGetRequest.mock.calls[0]?.[0]);

    expect(requestUrl).toBe(
      'https://api.example.test/v1/provider?planId=plan-1&serviceType=eQueuingTele&orderBy=queue&showOffline=false&doctorType=GP',
    );
    expect(requestUrl).not.toContain('payorId=');
    expect(requestUrl).not.toContain('specialty=');
    expect(requestUrl).not.toContain('region=');
    expect(requestUrl).not.toContain('page=');
    expect(requestUrl).not.toContain('limit=');
    expect(requestUrl).not.toContain('getRecommendedGp');
  });

  test('keeps the specialty list query for other doctor lists', async () => {
    await filterBySpecialty({
      payorId: 'payor-1',
      planId: 'plan-1',
      specialty: 'General Practice',
      region: 'China',
      page: 1,
      limit: 10,
    });

    expect(mockGetRequest).toHaveBeenCalledWith(
      'https://api.example.test/v1/provider?payorId=payor-1&planId=plan-1&specialty=General%20Practice&region=China&page=1&limit=10',
    );
  });
});

