export interface ConsultPassProduct {
  currencyCode: string;
  id: string;
  price: string;
}

const readDefaultPlanId = (response: unknown): string | undefined => {
  if (!response || typeof response !== 'object' || !('data' in response)) {
    return undefined;
  }

  const data = response.data;

  if (!data || typeof data !== 'object' || !('defaultPlanId' in data)) {
    return undefined;
  }

  return typeof data.defaultPlanId === 'string' &&
    data.defaultPlanId.trim().length > 0
    ? data.defaultPlanId.trim()
    : undefined;
};

const readProductPrice = (value: unknown): string | undefined => {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return String(value);
  }

  return typeof value === 'string' && value.trim().length > 0
    ? value.trim()
    : undefined;
};

const readPassProduct = (value: unknown): ConsultPassProduct | undefined => {
  if (!value || typeof value !== 'object') {
    return undefined;
  }

  const product = value as {
    currencyCode?: unknown;
    id?: unknown;
    price?: unknown;
  };
  const price = readProductPrice(product.price);

  if (
    typeof product.id !== 'string' ||
    product.id.trim().length === 0 ||
    typeof product.currencyCode !== 'string' ||
    product.currencyCode.trim().length === 0 ||
    !price
  ) {
    return undefined;
  }

  return {
    currencyCode: product.currencyCode.trim(),
    id: product.id.trim(),
    price,
  };
};

const readPassProducts = (response: unknown): ConsultPassProduct[] => {
  if (!response || typeof response !== 'object' || !('data' in response)) {
    return [];
  }

  return Array.isArray(response.data)
    ? response.data.flatMap((item: unknown): ConsultPassProduct[] => {
        const product = readPassProduct(item);

        return product ? [product] : [];
      })
    : [];
};

export const selectConsultPassProduct = (
  optionsResponse: unknown,
  productListResponse: unknown,
): ConsultPassProduct | undefined => {
  const defaultPlanId = readDefaultPlanId(optionsResponse);

  if (!defaultPlanId) {
    return undefined;
  }

  return readPassProducts(productListResponse).find(
    (product: ConsultPassProduct): boolean => product.id === defaultPlanId,
  );
};

export const formatConsultPassPrice = (product: ConsultPassProduct): string => {
  const amount = Number(product.price);
  const formattedAmount = Number.isFinite(amount)
    ? amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',')
    : product.price;

  return `${product.currencyCode} ${formattedAmount}`;
};

import {
  formatConsultPassPrice,
  selectConsultPassProduct,
} from '../src/screens/doctor-detail-screen/consult-pass-product';

describe('selectConsultPassProduct', () => {
  const productList = {
    success: true,
    data: [
      {
        id: 'other-product',
        currencyCode: 'HKD',
        price: '280',
      },
      {
        id: 'default-plan',
        currencyCode: 'HKD',
        price: 200,
      },
    ],
  };

  test('uses the product whose id matches provider options defaultPlanId', () => {
    expect(
      selectConsultPassProduct(
        {
          data: {
            defaultPlanId: 'default-plan',
          },
        },
        productList,
      ),
    ).toEqual({
      id: 'default-plan',
      currencyCode: 'HKD',
      price: '200',
    });
  });

  test('returns no product when defaultPlanId is missing or unmatched', () => {
    expect(
      selectConsultPassProduct(
        {
          data: {},
        },
        productList,
      ),
    ).toBeUndefined();
    expect(
      selectConsultPassProduct(
        {
          data: {
            defaultPlanId: 'missing-plan',
          },
        },
        productList,
      ),
    ).toBeUndefined();
  });
});

describe('formatConsultPassPrice', () => {
  test('formats the product currency and price for the consult dialog', () => {
    expect(
      formatConsultPassPrice({
        id: 'default-plan',
        currencyCode: 'HKD',
        price: '200',
      }),
    ).toBe('HKD 200.00');
  });
});

