const isUnsettledPurchaseFinishError = (error: unknown): boolean => {
  if (
    !axios.isAxiosError(error) ||
    error.response?.status !== HttpStatus.BadRequest ||
    !error.config?.url?.includes(`${HEALS_PASS_PURCHASE_PATH}/finish/`)
  ) {
    return false;
  }

  const data = error.response.data;

  if (!data || typeof data !== 'object' || !('error' in data)) {
    return false;
  }

  const responseError = data.error;

  if (!responseError || typeof responseError !== 'object') {
    return false;
  }

  const localizeKey =
    'localize_key' in responseError ? responseError.localize_key : undefined;
  const message = 'message' in responseError ? responseError.message : undefined;

  return (
    localizeKey === 'error.TRANSACTION_NOT_SETTLED' ||
    message === 'Transaction is not settled'
  );
};

