package com.healshealthcare.healspass

import android.content.Context
import android.util.Log
import android.webkit.WebView
import androidx.webkit.ProxyConfig
import androidx.webkit.ProxyController
import androidx.webkit.WebViewFeature
import java.io.InputStream
import java.io.OutputStream
import java.net.DatagramPacket
import java.net.DatagramSocket
import java.net.InetAddress
import java.net.InetSocketAddress
import java.net.ServerSocket
import java.net.Socket
import java.util.concurrent.Executors

/**
 * The device resolver maps api-staging.yedpay.com to an address whose
 * certificate is not that name. WebView then fails the checkout with a
 * hostname mismatch. This local proxy resolves WebView hosts through public
 * DNS and still lets WebView verify the certificate.
 */
object WebViewPublicDnsProxy {
  private const val TAG = "WebViewPublicDnsProxy"
  private val publicResolvers = arrayOf("8.8.8.8", "1.1.1.1")
  private val workers = Executors.newCachedThreadPool()

  fun start(context: Context) {
    try {
      WebView(context)
      if (!WebViewFeature.isFeatureSupported(WebViewFeature.PROXY_OVERRIDE)) {
        Log.w(TAG, "WebView proxy override is not supported")
        return
      }
      val server = ServerSocket()
      server.reuseAddress = true
      server.bind(InetSocketAddress("127.0.0.1", 0))
      workers.execute {
        while (!server.isClosed) {
          try {
            val client = server.accept()
            workers.execute { handleClient(client) }
          } catch (error: Exception) {
            if (!server.isClosed) {
              Log.w(TAG, "accept failed", error)
            }
          }
        }
      }
      val proxy = ProxyConfig.Builder()
        .addProxyRule("http://127.0.0.1:${server.localPort}")
        .build()
      ProxyController.getInstance().setProxyOverride(
        proxy,
        workers,
      ) { Log.i(TAG, "WebView public DNS proxy listening on ${server.localPort}") }
    } catch (error: Exception) {
      Log.e(TAG, "failed to start WebView public DNS proxy", error)
    }
  }

  private fun handleClient(client: Socket) {
    client.use { socket ->
      val input = socket.getInputStream()
      val output = socket.getOutputStream()
      val requestLine = readLine(input) ?: return
      while (true) {
        val header = readLine(input) ?: return
        if (header.isEmpty()) {
          break
        }
      }
      val parts = requestLine.split(" ")
      if (parts.size < 2 || !parts[0].equals("CONNECT", ignoreCase = true)) {
        output.write("HTTP/1.1 405 Method Not Allowed\r\n\r\n".toByteArray())
        return
      }
      val hostPort = parts[1].split(":")
      val host = hostPort[0]
      val port = hostPort.getOrNull(1)?.toIntOrNull() ?: 443
      val address = resolve(host)
      if (address == null) {
        output.write("HTTP/1.1 502 Bad Gateway\r\n\r\n".toByteArray())
        return
      }
      Log.i(TAG, "connect $host -> ${address.hostAddress}:$port")
      Socket().use { upstream ->
        upstream.connect(InetSocketAddress(address, port), 10000)
        output.write("HTTP/1.1 200 Connection Established\r\n\r\n".toByteArray())
        output.flush()
        val up = upstream.getInputStream()
        val down = upstream.getOutputStream()
        val forward = workers.submit { copy(input, down) }
        copy(up, output)
        forward.cancel(true)
      }
    }
  }

  private fun resolve(host: String): InetAddress? {
    if (host.isEmpty()) {
      return null
    }
    try {
      val literal = InetAddress.getByName(host)
      if (host == literal.hostAddress) {
        return literal
      }
    } catch (_: Exception) {
    }
    for (resolver in publicResolvers) {
      val address = queryA(resolver, host)
      if (address != null) {
        return address
      }
    }
    return try {
      InetAddress.getByName(host)
    } catch (_: Exception) {
      null
    }
  }

  private fun queryA(resolver: String, host: String): InetAddress? {
    val query = dnsQuery(host)
    DatagramSocket().use { socket ->
      socket.soTimeout = 2000
      val packet = DatagramPacket(query, query.size, InetAddress.getByName(resolver), 53)
      socket.send(packet)
      val buffer = ByteArray(512)
      val response = DatagramPacket(buffer, buffer.size)
      socket.receive(response)
      return firstARecord(buffer, response.length)
    }
  }

  private fun dnsQuery(host: String): ByteArray {
    val header = byteArrayOf(0x12, 0x34, 0x01, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
    val name = host.split('.').flatMap { label ->
      listOf(label.length.toByte()) + label.toByteArray(Charsets.US_ASCII).toList()
    }.toByteArray() + byteArrayOf(0)
    return header + name + byteArrayOf(0x00, 0x01, 0x00, 0x01)
  }

  private fun firstARecord(data: ByteArray, length: Int): InetAddress? {
    if (length < 12) {
      return null
    }
    val answerCount = ((data[6].toInt() and 0xFF) shl 8) or (data[7].toInt() and 0xFF)
    var index = skipName(data, 12).second + 4
    repeat(answerCount) {
      if (index >= length) {
        return null
      }
      index = skipName(data, index).second
      if (index + 10 > length) {
        return null
      }
      val type = ((data[index].toInt() and 0xFF) shl 8) or (data[index + 1].toInt() and 0xFF)
      val size = ((data[index + 8].toInt() and 0xFF) shl 8) or (data[index + 9].toInt() and 0xFF)
      index += 10
      if (type == 1 && size == 4 && index + 4 <= length) {
        return InetAddress.getByAddress(data.copyOfRange(index, index + 4))
      }
      index += size
    }
    return null
  }

  private fun skipName(data: ByteArray, start: Int): Pair<String, Int> {
    var index = start
    var end = start
    var jumped = false
    var hops = 0
    while (hops++ < 16 && index < data.size) {
      val length = data[index].toInt() and 0xFF
      if (length == 0) {
        if (!jumped) {
          end = index + 1
        }
        break
      }
      if (length and 0xC0 == 0xC0) {
        if (!jumped) {
          end = index + 2
        }
        if (index + 1 >= data.size) {
          break
        }
        index = ((length and 0x3F) shl 8) or (data[index + 1].toInt() and 0xFF)
        jumped = true
        continue
      }
      index += 1 + length
      if (!jumped) {
        end = index
      }
    }
    return "" to end
  }

  private fun readLine(input: InputStream): String? {
    val line = StringBuilder()
    while (line.length < 8192) {
      val value = input.read()
      if (value == -1) {
        return if (line.isEmpty()) null else line.toString()
      }
      if (value == '\n'.code) {
        if (line.isNotEmpty() && line[line.length - 1] == '\r') {
          line.setLength(line.length - 1)
        }
        return line.toString()
      }
      line.append(value.toChar())
    }
    return line.toString()
  }

  private fun copy(input: InputStream, output: OutputStream) {
    try {
      val buffer = ByteArray(8192)
      while (true) {
        val count = input.read(buffer)
        if (count < 0) {
          break
        }
        output.write(buffer, 0, count)
        output.flush()
      }
