private void reloadAllowedNavigation(WebView view, String url) {
    directLoadUrl = url;
    final String referer = checkoutReferer(view.getUrl(), url);
    view.post(() -> {
        if (referer == null) {
            view.loadUrl(url);
            return;
        }
        final Map<String, String> headers = new HashMap<>();
        headers.put("Referer", referer);
        view.loadUrl(url, headers);
    });
}

// Yedpay rejects a checkout whose request has no payment-page origin.
private String checkoutReferer(String currentUrl, String nextUrl) {
    if (currentUrl == null || nextUrl == null || !nextUrl.contains("yedpay.com")) {
        return null;
    }
    try {
        URI current = URI.create(currentUrl);
        if (current.getScheme() == null || current.getHost() == null) {
            return null;
        }
        return current.getScheme() + "://" + current.getHost() + "/";
    } catch (IllegalArgumentException ignored) {
        return null;
    }
}

