      }
      index += size
    }
    return nil
  }

  private static func skipName(_ data: [UInt8], start: Int) -> (String, Int) {
    var index = start
    var end = start
    var jumped = false
    var hops = 0
    while hops < 16 && index < data.count {
      hops += 1
      let length = Int(data[index])
      if length == 0 {
        if !jumped {
          end = index + 1
        }
        break
      }
      if length & 0xC0 == 0xC0 {
        if !jumped {
          end = index + 2
        }
        guard index + 1 < data.count else { break }
        index = ((length & 0x3F) << 8) | Int(data[index + 1])
        jumped = true
        continue
      }
      index += 1 + length
