        index = ((length & 0x3F) << 8) | Int(data[index + 1])
        jumped = true
        continue
      }
      index += 1 + length
      if !jumped {
        end = index
      }
    }
    return ("", end)
  }

  private static func readLine(_ fd: Int32) -> String? {
    var bytes: [UInt8] = []
    while bytes.count < 8192 {
      var value: UInt8 = 0
      let count = read(fd, &value, 1)
      if count <= 0 {
        return bytes.isEmpty ? nil : String(bytes: bytes, encoding: .utf8)
      }
      if value == 10 {
        if bytes.last == 13 {
          bytes.removeLast()
        }
        return String(bytes: bytes, encoding: .utf8) ?? ""
      }
      bytes.append(value)
    }
    return String(bytes: bytes, encoding: .utf8)
  }

  private static func writeString(_ fd: Int32, _ text: String) -> Int {
    let data = Array(text.utf8)
    return data.withUnsafeBytes { raw in
      write(fd, raw.baseAddress, data.count)
    }
  }

  private static func copy(from source: Int32, to destination: Int32) {
    var buffer = [UInt8](repeating: 0, count: 8192)
    while true {
      let count = buffer.withUnsafeMutableBytes { raw in
        read(source, raw.baseAddress, raw.count)
      }
      if count <= 0 {
        break
      }
      var sent = 0
      while sent < count {
        let written = buffer.withUnsafeBytes { raw in
          write(destination, raw.baseAddress! + sent, count - sent)
        }
        if written <= 0 {
          return
        }
        sent += written
      }
    }
  }
}

